import { error } from '@sveltejs/kit';
import packages from '$lib/data/packages.json';
import { highlight } from '$lib/server/highlight';
import type { EntryGenerator, PageServerLoad } from './$types';

// The site prerenders, so every package needs naming up front. The data is
// generated by script/packages.mjs, which is also what keeps the rule listings
// from drifting: they come out of the packages themselves.
export const entries: EntryGenerator = () => packages.map((p) => ({ name: p.name }));

export const load: PageServerLoad = async ({ params }) => {
	const pkg = packages.find((p) => p.name.toLowerCase() === params.name.toLowerCase());
	if (!pkg) {
		error(404, `No package named "${params.name}".`);
	}
	// A package can hold several styles, some meant as alternatives, so the
	// snippet turns on the one named for the package and lists the rest.
	const styles = [...new Set(pkg.rules.map((r) => r.style))];
	const core = styles.find((s) => s === pkg.name) ?? (styles.length === 1 ? styles[0] : '');
	const others = styles.filter((s) => s !== core);
	let snippet = `Packages = ${pkg.name}\n\n[*.md]\nBasedOnStyles = ${['Vale', core].filter(Boolean).join(', ')}`;
	if (others.length) {
		snippet += `\n\n# Also in this package; add the ones you want:\n# ${others.join(', ')}`;
	}

	// The name installs whatever release is latest when `vale sync` runs. A
	// pinned URL names the release the page shows, so a repository stays on
	// the rules it was reviewed with until someone moves it.
	let pin = '';
	if (pkg.version && pkg.repo) {
		const archive = pkg.url.split('/').pop();
		pin = `Packages = https://github.com/${pkg.repo}/releases/download/${pkg.version}/${archive}`;
	}
	return {
		pkg,
		snippet,
		snippetHtml: await highlight(snippet, 'ini'),
		pin,
		pinHtml: pin ? await highlight(pin, 'ini') : ''
	};
};
